def formula(household, period):
    country = household("country", period)
    countries = country.possible_values
    return np.isin(
        country.decode_to_str(),
        [countries.ENGLAND.name, countries.NORTHERN_IRELAND.name],
    )

# Load variable values for all years
for year in dataset.years:
    for table in dataset[year].tables:
        for variable in table.columns:
            if variable not in self.tax_benefit_system.variables:
                continue
            self.set_input(variable, year, table[variable])

def from_simulation(simulation: "Microsimulation", fiscal_year: int = 2025):
    entity_dfs = {}

    for entity in ["person", "benunit", "household"]:
        input_variables = [
            variable
            for variable in simulation.input_variables
            if simulation.tax_benefit_system.variables[variable].entity.key
            == entity
        ]
        if len(input_variables) == 0:
            entity_dfs[entity] = pd.DataFrame()
        else:
            entity_dfs[entity] = simulation.calculate_dataframe(
                input_variables, period=fiscal_year
            )

    return UKSingleYearDataset(
        person=entity_dfs["person"],
        benunit=entity_dfs["benunit"],
        household=entity_dfs["household"],
        fiscal_year=fiscal_year,
